"use server";

/**
 * Archives a project and, optionally, its issues.
 *
 * Owner D. `archiveIssues` defaults to true: leaving live issues under an
 * archived project is the state that makes every "open issues" count wrong, so
 * opting out has to be deliberate.
 *
 * Must call (do not reimplement): archiveProjectSchema, can, assertNotArchived,
 * getActor, toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { archiveProjectSchema, type ArchiveProjectInput } from "@/schemas/project";
import {
  archiveProject,
  listProjects,
} from "@/server/services/project-service";
import { ActionNotFoundError } from "@/actions/_lib/action-errors";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";

const run = withAction<typeof archiveProjectSchema, Project>(
  archiveProjectSchema,
  async (raw, actor) => {
    const input = raw as ArchiveProjectInput;

    const page = await listProjects(actor, {
      orgId: input.orgId,
      limit: 100,
      includeArchived: true,
    });
    const current = page.items.find((row) => row.project.id === input.projectId);
    if (current === undefined) {
      throw new ActionNotFoundError(`project ${input.projectId}`);
    }

    const allowed = can(actor, "project:archive", {
      kind: "project",
      orgId: input.orgId,
      projectId: input.projectId,
      visibility: current.project.visibility,
      leadId: current.project.leadId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:archive");
    }

    assertNotArchived("project", input.projectId, current.project);

    const project = await archiveProject(actor, input);
    revalidateTagged(
      [orgTag(input.orgId), projectTag(project.id)],
      CACHE_PROFILES.minutes,
    );
    return project;
  },
  { revalidate: ["projects", "issues"], cacheProfile: "minutes" },
);

export async function archiveProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
"use server";

/**
 * Creates a project after the plan's project quota is checked.
 *
 * Owner D. Archived projects still occupy the quota, so the count deliberately
 * includes them — restoring a project must never be blocked by a limit the
 * restore itself would breach.
 *
 * Must call (do not reimplement): createProjectSchema, can, getPlanLimits,
 * getActor, toActionResult
 */

import { ForbiddenActionError, PlanLimitError } from "@/actions/_lib/action-errors";
import { PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { withAction } from "@/actions/_lib/with-action";
import { getPlanLimits } from "@/config/plan-limits";
import { CACHE_PROFILES, orgTag, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { createProjectSchema, type CreateProjectInput } from "@/schemas/project";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { createProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";

const run = withAction<typeof createProjectSchema, Project>(
  createProjectSchema,
  async (raw, actor) => {
    const input = raw as CreateProjectInput;

    const allowed = can(actor, "project:create", {
      kind: "project",
      orgId: input.orgId,
      projectId: PENDING_PROJECT_ID,
      visibility: input.visibility,
      leadId: input.leadId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:create");
    }

    const summary = await getOrganizationSummary(actor, input.orgId);
    const limits = getPlanLimits(summary.organization.plan);
    if (summary.usage.projectsUsed >= limits.projects) {
      throw new PlanLimitError("projects", limits.projects, summary.usage.projectsUsed);
    }

    const project = await createProject(actor, input);
    revalidateTagged(
      [orgTag(input.orgId), projectTag(project.id)],
      CACHE_PROFILES.minutes,
    );
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function createProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
"use server";

/**
 * Restores an archived project.
 *
 * Owner D. There is no `restoreProjectSchema` in `src/schemas` because the
 * payload is nothing but the two ids, so the shape is composed here from the
 * shared branded-id primitives rather than added to the frozen schema layer.
 *
 * Must call (do not reimplement): can, restorePatch, getActor, toActionResult
 */

import { ActionNotFoundError, ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { restorePatch } from "@/lib/soft-delete";
import { orgIdSchema, projectIdSchema } from "@/schemas/common";
import { listProjects, restoreProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";
import { z } from "zod";

const restoreProjectSchema = z.object({
  orgId: orgIdSchema,
  projectId: projectIdSchema,
});

type RestoreProjectInput = z.infer<typeof restoreProjectSchema>;

const run = withAction<typeof restoreProjectSchema, Project>(
  restoreProjectSchema,
  async (raw, actor) => {
    const input = raw as RestoreProjectInput;

    const page = await listProjects(actor, {
      orgId: input.orgId,
      limit: 100,
      includeArchived: true,
    });
    const current = page.items.find((row) => row.project.id === input.projectId);
    if (current === undefined) {
      throw new ActionNotFoundError(`project ${input.projectId}`);
    }

    const allowed = can(actor, "project:archive", {
      kind: "project",
      orgId: input.orgId,
      projectId: input.projectId,
      visibility: current.project.visibility,
      leadId: current.project.leadId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:archive");
    }

    const project = await restoreProject(actor, input.orgId, input.projectId);

    // `restorePatch()` is the single definition of what "restored" looks like;
    // comparing against it catches a service that forgot to clear the column.
    const expected = restorePatch();
    if (project.archivedAt !== expected.archivedAt) {
      throw new ActionNotFoundError(`live project ${input.projectId}`);
    }

    revalidateTagged(
      [orgTag(input.orgId), projectTag(project.id)],
      CACHE_PROFILES.minutes,
    );
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function restoreProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
"use server";

/**
 * Updates project metadata.
 *
 * Owner D. Visibility is part of this payload, which is why the permission
 * resource carries the *incoming* visibility: raising a project to `public`
 * must be judged against what it is becoming, not what it was.
 *
 * Must call (do not reimplement): updateProjectSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { updateProjectSchema, type UpdateProjectInput } from "@/schemas/project";
import { updateProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";

const run = withAction<typeof updateProjectSchema, Project>(
  updateProjectSchema,
  async (raw, actor) => {
    const input = raw as UpdateProjectInput;

    const allowed = can(actor, "project:update", {
      kind: "project",
      orgId: input.orgId,
      projectId: input.projectId,
      visibility: input.visibility ?? "org",
      leadId: input.leadId ?? actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:update");
    }

    const project = await updateProject(actor, input);
    revalidateTagged([projectTag(project.id)], CACHE_PROFILES.minutes);
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function updateProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
/**
 * Project lifecycle including the project-count quota and the cascade that archives a project's issues.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, uniqueSlug, projectKeyFromName
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { projectKeyFromName, uniqueSlug } from "@/lib/slug";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  ArchiveProjectInput,
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { OrgId, Page, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

/**
 * Creates a project once the plan still has room for one. The key is derived
 * from the name when the caller left it blank, so the issue numbering scheme
 * (`TF-12`) is never invented at the call site.
 */
export async function createProject(
  actor: Actor,
  input: CreateProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const slug = await suggestProjectSlug(input.orgId, input.name);

  const project = await projectRepo.insertProject({
    ...input,
    slug,
    key: input.key || projectKeyFromName(input.name),
  });

  await emit("project.created", {
    ...actorEnvelope(actor),
    projectId: project.id,
    name: project.name,
    slug: project.slug,
  });

  return project;
}

export async function updateProject(
  actor: Actor,
  input: UpdateProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  return projectRepo.updateProject(input);
}

/**
 * Archiving a project cascades to its issues by default — leaving live issues
 * behind an archived project is the drift this flag exists to prevent.
 */
export async function archiveProject(
  actor: Actor,
  input: ArchiveProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:archive", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const issuesArchived = input.archiveIssues
    ? await issueRepo.archiveIssuesForProject(input.orgId, input.projectId)
    : 0;

  const archived = await projectRepo.archiveProject(
    input.orgId,
    input.projectId,
  );

  await emit("project.archived", {
    ...actorEnvelope(actor),
    projectId: archived.id,
    issuesArchived,
  });

  return archived;
}

/** Restore does not un-archive the issues: they are restored individually. */
export async function restoreProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:archive", projectResource(project));

  const restored = await projectRepo.restoreProject(orgId, projectId);

  await emit("project.restored", {
    ...actorEnvelope(actor),
    projectId: restored.id,
  });

  return restored;
}

export async function getProject(
  actor: Actor,
  orgId: OrgId,
  slug: string,
): Promise<ProjectWithStats> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectBySlug(orgId, slug),
    "Project",
    slug,
  );
  assertCan(actor, "project:read", projectResource(project));

  return {
    project,
    stats: await projectRepo.getProjectStats(orgId, project.id),
  };
}

export async function listProjects(
  actor: Actor,
  input: ListProjectsInput,
): Promise<Page<ProjectWithStats>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:read", orgResource(input.orgId));

  const page = await projectRepo.listProjects(input);

  const items = await Promise.all(
    page.items.map(async (project) => ({
      project,
      stats: await projectRepo.getProjectStats(input.orgId, project.id),
    })),
  );

  return { items, nextCursor: page.nextCursor, total: page.total };
}

/**
 * Slug preview used by both the create form and `createProject`, so what the
 * user sees while typing is what the row ends up with.
 */
export async function suggestProjectSlug(
  orgId: OrgId,
  name: string,
): Promise<string> {
  const taken = await projectRepo.listTakenProjectSlugs(orgId);
  return uniqueSlug(name, taken);
}
